    enum Result: String, Sendable, CaseIterable {
        case missingEpochBaseline = "missing_epoch_baseline"
        case missingEpoch = "missing_epoch"
        case seqRegression = "seq_regression"
        case epochBaseline = "epoch_baseline"
        case epochChanged = "epoch_changed"
        case noGap = "no_gap"
        case fetchFailed = "fetch_failed"
        case notLive = "not_live"
        case epochMismatch = "epoch_mismatch"
        case ringMiss = "ring_miss"
        case applied
        case alreadyConnected = "already_connected"
        case connected
        case timeout
        case willRetry = "will_retry"
        case delivered
        case gone
        case rejected
        case unavailable
        case failed
        case throttled
        case noActivity = "no_activity"
        case answered
        case empty
        case ignored
        case replayed
        case miss
        case transcribed
        case noAudio = "no_audio"
    }

    /// Why the event happened; each event narrows it.
    enum Reason: String, Sendable, CaseIterable {
        case cacheHit = "cache_hit"
        case conversationStream = "conversation_stream"
        case reconnectConversationStream = "reconnect_conversation_stream"
        case reconnectNoGap = "reconnect_no_gap"
        case reconnectApplied = "reconnect_applied"
        case reconnectFullReloadScheduled = "reconnect_full_reload_scheduled"
        case streamSeq = "stream_seq"
        case historyEmpty = "history_empty"
        case historyAppliedEmpty = "history_applied_empty"
        case historyDeferredToLive = "history_deferred_to_live"
        case historyUnchanged = "history_unchanged"
        case historyApplied = "history_applied"
        case historyReplayed = "history_replayed"
        case historyFirstMessageFallback = "history_first_message_fallback"
        case receiveError = "receive_error"
        case handshakeHttp = "handshake_http"
        case protocolClose = "protocol_close"
        case recoverableReceive = "recoverable_receive"
        case pingWatchdog = "ping_watchdog"
        case authCurrentToken = "auth_current_token"
        case authRefresh = "auth_refresh"
        case completed
        case stopped
        case error
        case idleTimeout = "idle_timeout"
        case serverRestart = "server_restart"
        case storeFailed = "store_failed"
        case leaseLost = "lease_lost"
        case notFound = "not_found"
        case launchInProgress = "launch_in_progress"
        case dictationUnavailable = "dictation_unavailable"
        case unsupportedMessage = "unsupported_message"
        case other
    }

    /// Coarse error class, one vocabulary for every event. Never a platform type name, error text, or code.
    enum ErrorKind: String, Sendable, CaseIterable {
        case network
        case timeout
        case decode
        case cancelled
        case notConnected = "not_connected"
        case noConnection = "no_connection"
        case noWorkspace = "no_workspace"
        case agentLaunchFailed = "agent_launch_failed"
        case requestFailed = "request_failed"
        case promptDelivery = "prompt_delivery"
        case httpStatus = "http_status"
        case urlError = "url_error"
        case misconfigured
        case captureBufferOverflow = "capture_buffer_overflow"
        case bluetoothRouteLost = "bluetooth_route_lost"
        case capturePipelineDead = "capture_pipeline_dead"
        case unsupportedMime = "unsupported_mime"
        case remoteError = "remote_error"
        case invalidFormat = "invalid_format"
        case oversizedChunk = "oversized_chunk"
        case avfoundation
        case stt
        case requestTooLarge = "request_too_large"
        case overloaded
        case rateLimit = "rate_limit"
        case auth
        case connect
        case config
        case jsonParse = "json_parse"
        case terminated
        case other
    }

    /// Step of the operation in which the event happened; each event narrows it.
    enum Phase: String, Sendable, CaseIterable {
        case initial
        case refresh
        case deferred
        case start
        case load
        case stream
        case activate
        case chunk
        case source
        case playerItem = "player_item"
        case playerState = "player_state"
        case stall
        case callStart = "call_start"
        case callEnd = "call_end"
        case dictationStart = "dictation_start"
    }

    /// Client connection transport path. `local` is on-device work with no server connection.
    enum Transport: String, Sendable, CaseIterable {
        case paired
        case lan
        case unix
        case local
    }

    /// Client network route. `system_vpn` is inferred: MagicDNS without a published embedded SOCKS proxy.
    enum Route: String, Sendable, CaseIterable {
        case lan
        case socks
        case systemVpn = "system_vpn"
        case paired
