    /// Session-configured Pi thinking level. Per-response reasoning can differ.
    enum Thinking: String, Sendable, CaseIterable {
        case off
        case minimal
        case low
        case medium
        case high
        case xhigh
        case max
    }

    /// Session runtime: `oppi` (classic SDK), `durable` (live durable engine), `pi-tui` (terminal mirror).
    enum Runtime: String, Sendable, CaseIterable {
        case oppi
        case durable
        case piTui = "pi-tui"
    }

    /// Push notification kind.
    enum Notification: String, Sendable, CaseIterable {
        case blocked
        case error
        case notify
        case pairingApproval = "pairing_approval"
        case deviceEnrolled = "device_enrolled"
        case liveActivityStart = "live_activity_start"
        case liveActivityUpdate = "live_activity_update"
        case liveActivityEnd = "live_activity_end"
    }

    /// What started a schedule run.
    enum RunKind: String, Sendable, CaseIterable {
        case due
        case manual
    }

    /// Whether `host_*` fields describe the machine or the container Oppi runs in (cgroup limits).
    enum HostScope: String, Sendable, CaseIterable {
        case host
        case container
    }

    /// How a screen's content was loaded.
    enum LoadPath: String, Sendable, CaseIterable {
        case cacheHit = "cache_hit"
        case cacheMiss = "cache_miss"
        case fullReload = "full_reload"
        case firstMessageFallback = "first_message_fallback"
        case conversationStream = "conversation_stream"
        case open
        case returnFromChat = "return_from_chat"
    }

    /// Where the timeline reducer rebuilt its state from.
    enum LoadSource: String, Sendable, CaseIterable {
        case cache
        case history
        case historyReplay = "history_replay"
        case historyFirstMessageFallback = "history_first_message_fallback"
    }

    /// Size class of a tool row's output.
    enum OutputSize: String, Sendable, CaseIterable {
        case under1kb = "under_1kb"
        case under10kb = "under_10kb"
        case under50kb = "under_50kb"
        case under200kb = "under_200kb"
        case over200kb = "over_200kb"

        /// The bucket for a measured value; edges are the server's.
        init(bytes: Int) {
            if bytes < 1000 {
                self = .under1kb
            } else if bytes < 10000 {
                self = .under10kb
            } else if bytes < 50000 {
                self = .under50kb
            } else if bytes < 200000 {
                self = .under200kb
            } else {
                self = .over200kb
            }
        }
    }

    /// Size class of the input a render step processed.
    enum InputSize: String, Sendable, CaseIterable {
        case under1kb = "under_1kb"
        case under10kb = "under_10kb"
        case under50kb = "under_50kb"
        case under200kb = "under_200kb"
        case over200kb = "over_200kb"

        /// The bucket for a measured value; edges are the server's.
        init(bytes: Int) {
            if bytes < 1000 {
                self = .under1kb
            } else if bytes < 10000 {
                self = .under10kb
            } else if bytes < 50000 {
                self = .under50kb
            } else if bytes < 200000 {
                self = .under200kb
            } else {
                self = .over200kb
            }
        }
    }

    /// Whether any agent session was running on the device.
    enum Agents: String, Sendable, CaseIterable {
        case running
        case idle
    }

    /// Whether voice input was active.
    enum Voice: String, Sendable, CaseIterable {
        case on
        case off
    }

    /// Client voice input engine: Apple SpeechTranscriber, Apple DictationTranscriber, or server dictation.
    enum VoiceEngine: String, Sendable, CaseIterable {
        case speech
        case dictation
        case server
    }

    /// How the dictation model or stream was obtained at setup.
    enum ModelPath: String, Sendable, CaseIterable {
        case warmCache = "warm_cache"
        case cold
        case joinPrewarm = "join_prewarm"
        case dictationAudioWs = "dictation_audio_ws"
    }

    /// Where speech-to-text runs.
    enum SttProviderKind: String, Sendable, CaseIterable {
        case onDevice = "on_device"
        case localServer = "local_server"
    }

    /// Set when capture fell back to the built-in microphone.
    enum AudioRoute: String, Sendable, CaseIterable {
        case builtInFallback = "built_in_fallback"
    }

    /// Kind of media being played.
    enum MediaKind: String, Sendable, CaseIterable {
        case video
        case audio
        case image
        case unknown
    }

    /// How an ask card encodes its answer.
    enum ResponseEncoding: String, Sendable, CaseIterable {
        case ask
        case select
        case confirm
        case input
    }

    /// Where a quick session was started: the in-app sheet or an App Intent.
    enum OriginSurface: String, Sendable, CaseIterable {
        case sheet
        case intent
    }

    /// Whether a session launched on the main worktree.
    enum Worktree: String, Sendable, CaseIterable {
        case main
        case other
    }

    /// Session engine chosen at launch.
    enum SessionEngine: String, Sendable, CaseIterable {
        case classic
        case durable
    }
}

