/// How long did a session command take to send and to resolve? Fire-and-forget commands have no round trip.
struct AppCommand: TelemetryEvent {
    static let name = "app.command"

    enum Transport: String, Sendable, CaseIterable {
        case paired
        case lan
        case unix
    }

    enum Status: String, Sendable, CaseIterable {
        case ok
        case cancelled
        case error
    }

    let sendMs: Double
    let roundtripMs: Double?
    let command: String
    let transport: Transport
    let status: Status
    let errorKind: TelemetryTag.ErrorKind?

    init(
        sendMs: Double,
        roundtripMs: Double? = nil,
        command: String,
        transport: Transport,
        status: Status,
        errorKind: TelemetryTag.ErrorKind? = nil
    ) {
        self.sendMs = sendMs
        self.roundtripMs = roundtripMs
        self.command = command
        self.transport = transport
        self.status = status
        self.errorKind = errorKind
    }

    var fieldValues: [String: Double] {
        var values: [String: Double] = [:]
        values["send_ms"] = sendMs
        if let roundtripMs { values["roundtrip_ms"] = roundtripMs }
        return values
    }

    var passesEmitPolicy: Bool {
        if let roundtripMs, command == "get_queue", status.rawValue == "ok", roundtripMs < 500 { return false }
        return true
    }

    var tagValues: [String: String] {
        var values: [String: String] = [:]
        values["command"] = TelemetryName.sanitize(command)
        values["transport"] = transport.rawValue
        values["status"] = status.rawValue
        if let errorKind { values["error_kind"] = errorKind.rawValue }
        return values
    }
}

